(function(E){ const x = E["hr-m5"] = E["hr-m5"] || {units:{}}; x.units["hr-cp-5"] = {"writing":{"id":"c-hr-cp-5-w","title":{"en":"Ece's review feedback","tr":"Ece'nin değerlendirme geri bildirimi","fa":"بازخورد ارزیابی اجه"},"course":"hr","unit":"hr-cp-5","portfolio":null,"type":"writing","difficulty":"hard","prompt":{"en":"Ece, a driver, has her six-month review. Write (1) one piece of positive and one piece of development feedback, each with situation, behaviour and impact, and (2) a three-line development plan: a goal with by + date, a recommended action (recommend + -ing) and a purpose (to + verb). 80-110 words in total.","tr":"Sürücü Ece'nin altı aylık değerlendirmesi var. (1) Her biri durum, davranış ve etki içeren bir olumlu ve bir gelişim geri bildirimi, (2) üç satırlık bir gelişim planı yaz: by + tarihli bir hedef, önerilen bir eylem (recommend + -ing) ve bir amaç (to + fiil). Toplam 80-110 kelime.","fa":"اجه، یکی از راننده‌ها، جلسه‌ی ارزیابی شش‌ماهه دارد. بنویس: (۱) یک بازخورد مثبت و یک بازخورد برای پیشرفت، هر کدام با موقعیت، رفتار و اثر؛ و (۲) یک برنامه‌ی توسعه‌ی فردی سه‌خطی: یک هدف با by و تاریخ، یک اقدام پیشنهادی (recommend با -ing) و منظور آن (to با فعل). در مجموع ۸۰ تا ۱۱۰ کلمه."},"model":"Positive: On 3 October, when a pallet fell in the loading bay, you stopped the work and called the supervisor at once. The effect was that nobody was hurt and the area was safe in ten minutes. Development: On 9 and 16 October, your fuel log was not filled in. This meant that accounts could not close the month on time. Development plan: Goal: complete the fuel log after every shift, with no gaps by 30 November. Action: I recommend using the new phone form instead of paper. Purpose: to make the log quicker to complete.","frame":"Positive: On ___, when ___, you ___. The effect was that ___. Development: On ___, ___. This meant that ___. Development plan: Goal: ___ by ___. Action: I recommend ___. Purpose: to ___.","words":[{"word":"effect"},{"word":"recommend"},{"word":"by"}],"minWords":80,"minSentences":7,"rubric":["Task done: two SBI pieces and a three-part plan","Organised: positive, development, plan","Language: past simple with dates; this meant / the effect was; recommend + -ing; to + verb; by + date","Tone: specific, fair, no labels"],"rubricI18n":{"tr":["Görev: iki SBI geri bildirimi ve üç parçalı bir plan","Düzen: olumlu, gelişim, plan","Dil: tarihlerle past simple; this meant / the effect was; recommend + -ing; to + fiil; by + tarih","Üslup: somut, adil, etiket yok"],"fa":["کامل بودن کار: دو بازخورد به روش SBI و یک برنامه‌ی سه‌بخشی","نظم: بازخورد مثبت، بازخورد پیشرفت، برنامه","زبان: گذشته‌ی ساده با تاریخ؛ this meant / the effect was؛ recommend با -ing؛ to با فعل؛ by با تاریخ","لحن: مشخص و منصف، بدون برچسب"]},"parts":[{"t":{"en":"Positive feedback: situation, behaviour, impact","tr":"Olumlu geri bildirim: durum, davranış, etki","fa":"بازخورد مثبت: موقعیت، رفتار، اثر"},"find":["positive","the effect was"],"sample":"a pallet fell; she stopped the work; nobody was hurt"},{"t":{"en":"Development feedback: situation, behaviour, impact","tr":"Gelişim geri bildirimi: durum, davranış, etki","fa":"بازخورد پیشرفت: موقعیت، رفتار، اثر"},"find":["development","this meant"],"sample":"fuel log not filled in; accounts could not close the month"},{"t":{"en":"A goal with by + date","tr":"by + tarih ile bir hedef","fa":"یک هدف با ⁨by⁩ و تاریخ"},"find":["goal","by 30 november","by"],"sample":"fuel log after every shift, no gaps by 30 November"},{"t":{"en":"A recommended action","tr":"Önerilen bir adım","fa":"یک اقدام پیشنهادی"},"find":["i recommend","recommend"],"sample":"using the new phone form"},{"t":{"en":"A purpose with to","tr":"to ile bir amaç","fa":"یک هدف با ⁨to⁩"},"find":["purpose","to make"],"sample":"to make the log quicker to complete"}]},"speaking":{"id":"hr-cp-5-sp","course":"hr","unit":"hr-cp-5","rounds":[120,90],"topic":{"en":"Giving Ece Her Feedback","tr":"Ece'ye Geri Bildirimini Vermek","fa":"بازخورد دادن به اجه"},"warmup":{"en":"Read your written feedback once. Underline the date, the behaviour and the impact in each piece.","tr":"Yazdığın geri bildirimi bir kez oku. Her birinde tarihi, davranışı ve etkiyi işaretle.","fa":"بازخورد نوشته‌شده‌ات را یک بار بخوان و در هر کدام زیر تاریخ، رفتار و اثر خط بکش."},"questions":[{"en":"Open the meeting: purpose and that it is two-way.","tr":"Toplantıyı aç: amaç ve karşılıklı olduğu.","fa":"جلسه را شروع کن: هدف جلسه و اینکه گفتگویی دوطرفه است."},{"en":"Give the positive feedback, then the development feedback, without reading.","tr":"Metne bakmadan, önce olumlu sonra gelişim geri bildirimini ver.","fa":"بدون نگاه کردن به متن، اول بازخورد مثبت و بعد بازخورد پیشرفت را بگو."},{"en":"Ask for her view and agree the goal and date.","tr":"Görüşünü sor ve hedef ile tarih üzerinde anlaşın.","fa":"نظرش را بپرس و روی هدف و تاریخ آن با او توافق کن."}],"followups":[{"en":"Say it out loud in 2 minutes, then in 90 seconds.","tr":"Yüksek sesle söyle: önce 2 dakikada, sonra 90 saniyede.","fa":"آن را با صدای بلند بگو: یک بار در دو دقیقه و بعد در ۹۰ ثانیه."}],"expressions":[{"phrase":"On (date), when..., you...","meaning":{"en":"Situation and behaviour.","tr":"Durum ve davranış.","fa":"موقعیت و رفتار را مشخص می‌کند."}},{"phrase":"This meant that...","meaning":{"en":"Impact.","tr":"Etki.","fa":"اثر را می‌گوید."}},{"phrase":"How do you see it?","meaning":{"en":"Invites her view.","tr":"Görüşünü ister.","fa":"نظر او را جویا می‌شود."}}]},"perspective":{"id":"c-hr-cp-5-p","title":{"en":"Ece hears her feedback","tr":"Ece geri bildirimini dinliyor","fa":"اجه بازخوردش را می‌شنود"},"course":"hr","unit":"hr-cp-5","type":"perspective","minSentences":3,"prompt":{"en":"You are Ece, hearing your feedback. Write 3 sentences in first person: which part surprised you, which part felt fair, and what will you do differently tomorrow?","tr":"Geri bildirimini dinleyen Ece'sin. Birinci tekil şahısla 3 cümle yaz: hangi kısım seni şaşırttı, hangisi adil geldi ve yarın neyi farklı yapacaksın?","fa":"تو اجه هستی و داری بازخوردت را می‌شنوی. از زبان خودت سه جمله بنویس: کدام بخش غافلگیرت کرد، کدام بخش منصفانه بود و فردا چه کاری را جور دیگری انجام می‌دهی؟"}},"exit":{"id":"c-hr-cp-5-x","course":"hr","unit":"hr-cp-5","type":"exit","note":"8 spaced items across modules 1-5.","items":[{"from":"hr-1-3","kind":"blank","prompt":"Sorry, did you ___ Hasan or Hana?","options":["say","said","says"],"correct":0,"point":2,"why":{"en":"say: after 'did you', the plain verb. 'Said' doubles the past, and 'says' is the present.","tr":"say: 'did you'dan sonra yalın fiil. 'Said' geçmişi iki kez söyler; 'says' şimdiki zamandır.","fa":"say درست است، چون بعد از did you فعل ساده می‌آید. said گذشته را دو بار می‌گوید و says زمان حال است."}},{"from":"hr-2-2","kind":"blank","prompt":"We want coordinators ___ enjoy solving problems.","options":["what","who","whose"],"correct":1,"point":2,"why":{"en":"who: it refers to people. 'What' can't join a clause to a noun, and 'whose' shows ownership.","tr":"who: insanları anlatır. 'What' bir yan cümleyi isme bağlayamaz; 'whose' sahiplik gösterir.","fa":"who درست است، چون به آدم‌ها برمی‌گردد. what جمله را به اسم وصل نمی‌کند و whose مالکیت را نشان می‌دهد."}},{"from":"hr-3-2","kind":"blank","prompt":"Can you tell me why ___ that decision?","options":["did you make","you made","made you"],"correct":1,"point":2,"why":{"en":"you made: inside 'Can you tell me why...', use statement order. 'Did you make' is question order, and 'made you' swaps subject and verb.","tr":"you made: 'Can you tell me why...' içinde düz sıra kullanılır. 'Did you make' soru sırasıdır; 'made you' özne ile fiilin yerini değiştirir.","fa":"you made درست است، چون بعد از Can you tell me why ترتیب خبری می‌آید. did you make ترتیب سؤالی است و made you جای فاعل و فعل را عوض می‌کند."}},{"from":"hr-3-4","kind":"blank","prompt":"I'm afraid that on this occasion the role ___ to another candidate.","options":["has been offered","has offered","offered"],"correct":0,"point":2,"why":{"en":"has been offered: the role receives the action, so has been + past participle. 'Has offered' says the role offered something, and 'offered' alone does too.","tr":"has been offered: görev eylemi alır, bu yüzden has been + üçüncü hâl. 'Has offered' ve tek başına 'offered' görevin bir şey önerdiğini söyler.","fa":"has been offered درست است، چون سمت به کسی پیشنهاد شده و has been و اسم مفعول لازم است. has offered و offered هر دو یعنی خود سمت چیزی پیشنهاد داده."}},{"from":"hr-4-4","kind":"blank","prompt":"I've ___ that the reports have been late.","options":["notice","noticed","noticing"],"correct":1,"point":2,"why":{"en":"noticed: 'I've' + past participle. 'Notice' and 'noticing' are not past participles.","tr":"noticed: 'I've' + üçüncü hâl. 'Notice' ve 'noticing' üçüncü hâl değildir.","fa":"noticed درست است، چون I've با اسم مفعول می‌آید. notice و noticing اسم مفعول نیستند."}},{"from":"hr-5-1","kind":"blank","prompt":"Reduce errors to zero ___ 31 March.","options":["since","during","by"],"correct":2,"point":2,"why":{"en":"by: 'by 31 March' is a deadline. 'Since' looks back, and 'during' is the time inside a period.","tr":"by: 'by 31 March' bir son tarihtir. 'Since' geriye bakar; 'during' bir dönemin içindeki zamandır.","fa":"by درست است، چون by 31 March مهلت است. since به عقب نگاه می‌کند و during یعنی در طول یک دوره."}},{"from":"hr-5-2","kind":"blank","prompt":"The effect ___ that the client complained.","options":["was","were","is being"],"correct":0,"point":2,"why":{"en":"was: 'the effect' is singular and the event is past. 'Were' is plural, and 'is being' is wrong for a result.","tr":"was: 'the effect' tekildir ve olay geçmiştedir. 'Were' çoğuldur; 'is being' bir sonuç için yanlıştır.","fa":"was درست است، چون the effect مفرد است و اتفاق در گذشته است. were جمع است و is being برای نتیجه غلط است."}},{"from":"hr-5-4","kind":"blank","prompt":"I suggest ___ a short course.","options":["to take","taking","take"],"correct":1,"point":2,"why":{"en":"taking: 'suggest' takes -ing. 'To take' and 'take' don't follow suggest this way.","tr":"taking: 'suggest' -ing alır. 'To take' ve 'take' suggest'ten sonra bu şekilde gelmez.","fa":"taking درست است، چون بعد از suggest فعل ing‌دار می‌آید. to take و take این‌طور بعد از suggest نمی‌آیند."}}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
